body.script:
(function () {
    const workspace = document.querySelector(".rw-workspace");
    const doc = document.getElementById("rw-document");
    const saveUrl = workspace.dataset.saveUrl;
    const saveButton = document.getElementById("rw-save-fields");
    const addButton = document.getElementById("rw-add-signature");
    const status = document.getElementById("rw-status");
    const propLabel = document.getElementById("rw-prop-label");
    const propType = document.getElementById("rw-prop-type");
    const propPage = document.getElementById("rw-prop-page");
    const propX = document.getElementById("rw-prop-x");
    const propY = document.getElementById("rw-prop-y");
    const propWidth = document.getElementById("rw-prop-width");
    const propHeight = document.getElementById("rw-prop-height");
    const propRequired = document.getElementById("rw-prop-required");
    const deleteButton = document.getElementById("rw-delete-field");
    let active = null;
    let drag = null;
    let toolDrag = null;
    let suppressToolClick = false;

    function setStatus(message) {
        if (status) {
            status.textContent = message || "";
        }
    }

    function rectPercent(element) {
        const parent = doc.getBoundingClientRect();
        const rect = element.getBoundingClientRect();
        return {
            pos_x: ((rect.left - parent.left) / parent.width) * 100,
            pos_y: ((rect.top - parent.top) / parent.height) * 100,
            width: (rect.width / parent.width) * 100,
            height: (rect.height / parent.height) * 100,
        };
    }

    function selectField(field) {
        if (active) {
            active.classList.remove("active");
        }
        active = field;
        if (!active) {
            return;
        }
        active.classList.add("active");
        propLabel.value = active.dataset.label || active.textContent.trim();
        propType.value = active.dataset.fieldType || "signature";
        propPage.value = active.dataset.page || "1";
        propRequired.checked = active.dataset.required !== "0";
        syncPropsFromActive();
    }

    function cleanPercent(value) {
        return parseFloat(String(value || "0").replace("%", "")) || 0;
    }

    function syncPropsFromActive() {
        if (!active) {
            return;
        }
        propX.value = cleanPercent(active.style.left).toFixed(1);
        propY.value = cleanPercent(active.style.top).toFixed(1);
        propWidth.value = cleanPercent(active.style.width).toFixed(1);
        propHeight.value = cleanPercent(active.style.height).toFixed(1);
    }

    function addField(type, point) {
        const field = document.createElement("div");
        field.className = "rw-field";
        field.dataset.id = "";
        field.dataset.fieldType = type || "signature";
        field.dataset.label = type === "date" ? "Date" : type === "text" ? "Text" : type === "initial" ? "Initials" : "Signature";
        field.dataset.required = "1";
        field.dataset.page = "1";
        field.style.left = point ? point.left + "%" : "8%";
        field.style.top = point ? point.top + "%" : "70%";
        field.style.width = type === "date" ? "16%" : "28%";
        field.style.height = "8%";
        field.innerHTML = "" + field.dataset.label + "";
        doc.appendChild(field);
        bindField(field);
        selectField(field);
        setStatus("");
    }

    function bindField(field) {
        field.addEventListener("pointerdown", function (event) {
            selectField(field);
            const isResize = event.target.classList.contains("rw-resize");
            const parent = doc.getBoundingClientRect();
            const start = field.getBoundingClientRect();
            field.setPointerCapture(event.pointerId);
            drag = {
                field,
                isResize,
                startX: event.clientX,
                startY: event.clientY,
                left: start.left - parent.left,
                top: start.top - parent.top,
                width: start.width,
                height: start.height,
                parent,
                pointerId: event.pointerId,
            };
            event.preventDefault();
        });
        field.addEventListener("pointermove", moveField);
        field.addEventListener("pointerup", stopField);
        field.addEventListener("pointercancel", stopField);
    }

    function moveField(event) {
        if (!drag) {
            return;
        }
        if (drag.pointerId !== event.pointerId) {
            return;
        }
        const dx = event.clientX - drag.startX;
        const dy = event.clientY - drag.startY;
        if (drag.isResize) {
            const width = Math.max(80, drag.width + dx);
            const height = Math.max(34, drag.height + dy);
            drag.field.style.width = (width / drag.parent.width) * 100 + "%";
            drag.field.style.height = (height / drag.parent.height) * 100 + "%";
        } else {
            const left = Math.max(0, Math.min(drag.parent.width - drag.width, drag.left + dx));
            const top = Math.max(0, Math.min(drag.parent.height - drag.height, drag.top + dy));
            drag.field.style.left = (left / drag.parent.width) * 100 + "%";
            drag.field.style.top = (top / drag.parent.height) * 100 + "%";
        }
        if (drag.field === active) {
            syncPropsFromActive();
        }
        event.preventDefault();
    }

    function stopField(event) {
        if (!drag) {
            return;
        }
        if (drag.pointerId === event.pointerId) {
            drag = null;
        }
    }

    document.querySelectorAll(".rw-field").forEach(bindField);
    document.querySelectorAll(".rw-tool").forEach(function (button) {
        button.addEventListener("click", function () {
            if (suppressToolClick) {
                suppressToolClick = false;
                return;
            }
            addField(button.dataset.type);
        });
        button.addEventListener("pointerdown", function (event) {
            toolDrag = {
                type: button.dataset.type,
                ghost: makeToolGhost(button.textContent.trim(), event.clientX, event.clientY),
            };
            event.preventDefault();
        });
        button.addEventListener("dragstart", function (event) {
            event.dataTransfer.effectAllowed = "copy";
            event.dataTransfer.setData("text/plain", button.dataset.type);
        });
    });
    document.addEventListener("pointermove", function (event) {
        if (!toolDrag) { return; }
        toolDrag.ghost.style.left = event.clientX + 12 + "px";
        toolDrag.ghost.style.top = event.clientY + 12 + "px";
    });
    document.addEventListener("pointerup", function (event) {
        if (!toolDrag) { return; }
        const parent = doc.getBoundingClientRect();
        const inside = (
            event.clientX >= parent.left &&
            event.clientX <= parent.right &&
            event.clientY >= parent.top &&
            event.clientY <= parent.bottom
        );
        if (inside) {
            addField(toolDrag.type, {
                left: Math.max(0, Math.min(92, ((event.clientX - parent.left) / parent.width) * 100)),
                top: Math.max(0, Math.min(92, ((event.clientY - parent.top) / parent.height) * 100)),
            });
            suppressToolClick = true;
        }
        toolDrag.ghost.remove();
        toolDrag = null;
    });
    function makeToolGhost(label, x, y) {
        const ghost = document.createElement("div");
        ghost.className = "rw-tool-ghost";
        ghost.textContent = label;
        ghost.style.left = x + 12 + "px";
        ghost.style.top = y + 12 + "px";
        document.body.appendChild(ghost);
        return ghost;
    }
    doc.addEventListener("dragover", function (event) {
        event.preventDefault();
    });
    doc.addEventListener("drop", function (event) {
        event.preventDefault();
        const type = event.dataTransfer.getData("text/plain") || "signature";
        const parent = doc.getBoundingClientRect();
        addField(type, {
            left: Math.max(0, Math.min(92, ((event.clientX - parent.left) / parent.width) * 100)),
            top: Math.max(0, Math.min(92, ((event.clientY - parent.top) / parent.height) * 100)),
        });
    });
    addButton.addEventListener("click", function () { addField("signature"); });
    propLabel.addEventListener("input", function () {
        if (!active) { return; }
        active.dataset.label = propLabel.value;
        active.querySelector("span").textContent = propLabel.value;
    });
    propType.addEventListener("change", function () {
        if (!active) { return; }
        active.dataset.fieldType = propType.value;
    });
    propPage.addEventListener("input", function () {
        if (!active) { return; }
        active.dataset.page = propPage.value || "1";
    });
    function bindPercentInput(input, property) {
        input.addEventListener("input", function () {
            if (!active) { return; }
            const value = Math.max(0, Math.min(100, parseFloat(input.value || "0")));
            active.style[property] = value + "%";
            syncPropsFromActive();
        });
    }
    bindPercentInput(propX, "left");
    bindPercentInput(propY, "top");
    bindPercentInput(propWidth, "width");
    bindPercentInput(propHeight, "height");
    propRequired.addEventListener("change", function () {
        if (!active) { return; }
        active.dataset.required = propRequired.checked ? "1" : "0";
    });
    deleteButton.addEventListener("click", function () {
        if (!active) { return; }
        active.remove();
        active = null;
    });
    saveButton.addEventListener("click", function () {
        if (!saveUrl) {
            setStatus("Save URL is missing.");
            return;
        }
        saveButton.disabled = true;
        setStatus("Saving...");
        const items = Array.from(document.querySelectorAll(".rw-field")).map(function (field) {
            const pct = rectPercent(field);
            return {
                id: field.dataset.id ? parseInt(field.dataset.id, 10) : false,
                field_type: field.dataset.fieldType || "signature",
                label: field.dataset.label || field.textContent.trim(),
                required: field.dataset.required !== "0",
                page: parseInt(field.dataset.page || "1", 10),
                pos_x: pct.pos_x,
                pos_y: pct.pos_y,
                width: pct.width,
                height: pct.height,
            };
        });
        fetch(saveUrl, {
            method: "POST",
            headers: {"Content-Type": "application/json"},
            body: JSON.stringify({jsonrpc: "2.0", method: "call", params: {items: items}}),
        }).then(function (response) {
            return response.json();
        }).then(function (payload) {
            if (payload.error) {
                throw new Error(payload.error.data && payload.error.data.message ? payload.error.data.message : "Save failed.");
            }
            setStatus("Saved.");
            window.location.reload();
        }).catch(function (error) {
            setStatus(error.message || "Save failed.");
            saveButton.disabled = false;
        });
    });
})();

(function () {
    const form = document.getElementById("rw-sign-form");
    if (!form) { return; }
    const payloadInput = document.getElementById("item_payload");
    const firstSignatureInput = document.getElementById("signature_data");
    const signerNameInput = document.getElementById("rw-signer-name");
    const canvases = Array.from(document.querySelectorAll("canvas[data-canvas-id]"));
    const contexts = new Map();
    let activeCanvas = null;
    let drawing = false;

    function setupCanvas(canvas) {
        const context = canvas.getContext("2d");
        contexts.set(canvas.dataset.canvasId, {canvas: canvas, context: context, signed: false});
        resizeCanvas(canvas, context);
    }
    function resizeCanvas(canvas, context) {
        const ratio = Math.max(window.devicePixelRatio || 1, 1);
        const rect = canvas.getBoundingClientRect();
        canvas.width = rect.width * ratio;
        canvas.height = rect.height * ratio;
        context.setTransform(ratio, 0, 0, ratio, 0, 0);
        context.lineCap = "round";
        context.lineJoin = "round";
        context.lineWidth = 2.2;
        context.strokeStyle = "#082f49";
    }
    function point(canvas, event) {
        const rect = canvas.getBoundingClientRect();
        const source = event.touches ? event.touches[0] : event;
        return {x: source.clientX - rect.left, y: source.clientY - rect.top};
    }
    function start(event) {
        const canvas = event.target;
        const item = contexts.get(canvas.dataset.canvasId);
        activeCanvas = canvas;
        drawing = true;
        item.signed = true;
        const p = point(canvas, event);
        item.context.beginPath();
        item.context.moveTo(p.x, p.y);
        event.preventDefault();
    }
    function draw(event) {
        if (!drawing || !activeCanvas) { return; }
        const item = contexts.get(activeCanvas.dataset.canvasId);
        const p = point(activeCanvas, event);
        item.context.lineTo(p.x, p.y);
        item.context.stroke();
        event.preventDefault();
    }
    function stop(event) {
        drawing = false;
        activeCanvas = null;
        if (event) { event.preventDefault(); }
    }
    function fillAutoSignature(item, text) {
        const canvas = item.canvas;
        const context = item.context;
        context.clearRect(0, 0, canvas.width, canvas.height);
        const rect = canvas.getBoundingClientRect();
        context.save();
        context.font = "600 " + Math.max(18, rect.height * 0.36) + "px Segoe UI, Arial";
        context.fillStyle = "#172554";
        context.textAlign = "center";
        context.textBaseline = "middle";
        context.fillText(text || "Signature", rect.width / 2, rect.height / 2);
        context.restore();
        item.signed = true;
    }
    function fillUploadedSignature(item, image) {
        const canvas = item.canvas;
        const context = item.context;
        const rect = canvas.getBoundingClientRect();
        context.clearRect(0, 0, canvas.width, canvas.height);
        context.drawImage(image, 8, 8, Math.max(20, rect.width - 16), Math.max(20, rect.height - 16));
        item.signed = true;
    }
    canvases.forEach(function (canvas) {
        setupCanvas(canvas);
        canvas.addEventListener("mousedown", start);
        canvas.addEventListener("mousemove", draw);
        canvas.addEventListener("mouseup", stop);
        canvas.addEventListener("mouseleave", stop);
        canvas.addEventListener("touchstart", start, { passive: false });
        canvas.addEventListener("touchmove", draw, { passive: false });
        canvas.addEventListener("touchend", stop, { passive: false });
    });
    window.addEventListener("resize", function () {
        contexts.forEach(function (item) { resizeCanvas(item.canvas, item.context); });
    });
    document.getElementById("rw-clear-signature").addEventListener("click", function () {
        contexts.forEach(function (item) {
            item.context.clearRect(0, 0, item.canvas.width, item.canvas.height);
            item.signed = false;
        });
        document.querySelectorAll("input[data-input-id]").forEach(function (input) { input.value = ""; });
    });
    document.getElementById("rw-auto-signature").addEventListener("click", function () {
        contexts.forEach(function (item) {
            fillAutoSignature(item, signerNameInput.value);
        });
    });
    document.getElementById("rw-upload-trigger").addEventListener("click", function () {
        document.getElementById("rw-upload-signature").click();
    });
    document.getElementById("rw-upload-signature").addEventListener("change", function (event) {
        let file = false;
        if (event.target.files) {
            file = event.target.files[0];
        }
        if (!file) { return; }
        const reader = new FileReader();
        reader.onload = function () {
            const image = new Image();
            image.onload = function () {
                contexts.forEach(function (item) {
                    fillUploadedSignature(item, image);
                });
            };
            image.src = reader.result;
        };
        reader.readAsDataURL(file);
    });
    form.addEventListener("submit", function (event) {
        const payload = {};
        let firstSignature = "";
        let missing = false;
        document.querySelectorAll(".rw-sign-box").forEach(function (box) {
            const id = box.dataset.itemId;
            if (box.dataset.type === "signature" || box.dataset.type === "initial") {
                const item = contexts.get(id);
                let data = "";
                if (item) {
                    if (item.signed) {
                        data = item.canvas.toDataURL("image/png");
                    }
                }
                if (box.dataset.required === "1") {
                    if (!data) { missing = true; }
                }
                payload[id] = {signature_data: data};
                if (!firstSignature) {
                    if (data) { firstSignature = data; }
                }
            } else {
                const input = box.querySelector("input");
                const value = input ? input.value : "";
                if (box.dataset.required === "1") {
                    if (!value) { missing = true; }
                }
                payload[id] = {value: value};
            }
        });
        if (missing) {
            event.preventDefault();
            alert("Please complete all required fields.");
            return;
        }
        payloadInput.value = JSON.stringify(payload);
        firstSignatureInput.value = firstSignature;
    });
})();
